query:
INSERT INTO tool_categories (slug, name, description, icon, abstractActions) VALUES ('paid_ads', 'Paid Advertising', 'Paid ad campaigns — spend, performance, and audience insights', 'TrendingUp', '["get_campaigns","get_spend","get_conversions","get_audience","get_roas","get_top_ads"]') ON DUPLICATE KEY UPDATE name=name;

INSERT INTO tool_providers (categoryId, slug, name, description, authType, baseApiUrl) SELECT id, 'meta_ads', 'Meta Ads', 'Facebook & Instagram advertising', 'oauth2', 'https://graph.facebook.com' FROM tool_categories WHERE slug='paid_ads' ON DUPLICATE KEY UPDATE name=name;

INSERT INTO tool_providers (categoryId, slug, name, description, authType, baseApiUrl) SELECT id, 'google_ads', 'Google Ads', 'Google search and display advertising', 'oauth2', 'https://googleads.googleapis.com' FROM tool_categories WHERE slug='paid_ads' ON DUPLICATE KEY UPDATE name=name;

INSERT INTO tool_providers (categoryId, slug, name, description, authType, baseApiUrl) SELECT id, 'tiktok_ads', 'TikTok Ads', 'TikTok advertising platform', 'oauth2', 'https://business-api.tiktok.com' FROM tool_categories WHERE slug='paid_ads' ON DUPLICATE KEY UPDATE name=name;

INSERT INTO tool_providers (categoryId, slug, name, description, authType, baseApiUrl) SELECT id, 'ga4', 'Google Analytics 4', 'GA4 web analytics', 'oauth2', 'https://analyticsdata.googleapis.com' FROM tool_categories WHERE slug='analytics' ON DUPLICATE KEY UPDATE name=name;

